import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"SDK","description":"Official SDKs wrap native JSON only. One page per language: install, Quick start, full reference.","frontmatter":{"title":"SDK","description":"Official SDKs wrap native JSON only. One page per language: install, Quick start, full reference."},"headers":[],"relativePath":"en/api/sdk/index.md","filePath":"en/api/sdk/index.md","lastUpdated":1790057721000}`),a={name:`en/api/sdk/index.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="sdk" tabindex="-1">SDK <a class="header-anchor" href="#sdk" aria-label="Permalink to “SDK”">​</a></h1><p>Official SDKs wrap <strong>native JSON</strong> only (check, download, verify, optional delta/pack, optional replace). They do <strong>not</strong> implement Sparkle / electron-updater / WinGet store protocols.</p><p>Read install → Quick start until one <code>check</code> succeeds. Custom Transport / delta / in-use file replace / embedded networking: the rest of that language page plus <a href="./concepts">Concepts</a>. Store protocols: Electron/Sparkle scenario pages.</p><p>Treat documented versions such as <code>0.1.0</code> as placeholders for the current published version.</p><h2 id="install-matrix" tabindex="-1">Install matrix <a class="header-anchor" href="#install-matrix" aria-label="Permalink to “Install matrix”">​</a></h2><table tabindex="0"><thead><tr><th>Language</th><th>Install</th><th>Minimum</th><th>Source branch</th></tr></thead><tbody><tr><td>Python</td><td><code>pip install kirivers-client</code></td><td>Python 3.10+</td><td><code>sdk/python</code></td></tr><tr><td>Java</td><td>Maven <code>official.kirizu:kirivers-client</code></td><td>JDK 17</td><td><code>sdk/java</code></td></tr><tr><td>Kotlin</td><td><code>official.kirizu:kirivers-client-kotlin</code> (not a Java wrapper)</td><td>JDK 17</td><td><code>sdk/kotlin</code></td></tr><tr><td>C#</td><td><code>dotnet add package Kirizu.KiriVers.Client</code></td><td>.NET 8</td><td><code>sdk/csharp</code></td></tr><tr><td>TypeScript</td><td><code>npm install @kirizu/kirivers-client</code></td><td>Node 20+ / Electron main; <strong>not browsers</strong></td><td><code>sdk/typescript</code></td></tr><tr><td>Rust</td><td>crates.io <code>kirivers-client</code></td><td>Blocking API, no tokio required</td><td><code>sdk/rust</code></td></tr><tr><td>Dart</td><td><code>dart pub add kirivers_client</code></td><td>Dart 3; Flutter apps yes, <strong>Web no</strong></td><td><code>sdk/dart</code></td></tr><tr><td>C</td><td><code>git clone -b sdk/c https://github.com/Kirizu-Official/KiriVers.git</code></td><td>C11; CMake hosted or embedded</td><td><code>sdk/c</code></td></tr><tr><td>C++</td><td><code>git clone -b sdk/cpp …</code></td><td>C++17</td><td><code>sdk/cpp</code></td></tr><tr><td>Go</td><td><code>go get github.com/Kirizu-Official/KiriVers-SDK-Go</code> (<strong>separate repo</strong>)</td><td>Go modules</td><td>Publish repo; source <code>sdk/go-src</code>; <code>sdk/go</code> is a pointer</td></tr><tr><td>PHP</td><td><code>composer require kirizu/kirivers-client</code> (repo <code>KiriVers-SDK-PHP</code>)</td><td>PHP 8.2+, no Guzzle</td><td><code>sdk/php-src</code>; <code>sdk/php</code> is a pointer</td></tr><tr><td>Swift</td><td>SPM <code>https://github.com/Kirizu-Official/KiriVers-SDK-Swift.git</code></td><td>Apple toolchain; do not add the server repo in Xcode</td><td><code>sdk/swift-src</code>; <code>sdk/swift</code> is a pointer</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Packages or dedicated GitHub repositories may be unpublished</p><p>Each language page includes a clone fallback. <strong>Do not</strong> <code>go get</code> / Packagist / SPM the server repo <code>main</code> or pointer branches <code>sdk/go</code>, <code>sdk/php</code>, <code>sdk/swift</code>.</p></div><h2 id="shared-rules" tabindex="-1">Shared rules <a class="header-anchor" href="#shared-rules" aria-label="Permalink to “Shared rules”">​</a></h2><ol><li>The caller supplies <code>base_url</code>, <code>project_ref</code>, current version, os/arch, channel, and a stable app-generated <code>device_id</code> (the SDK never mints device identity).</li><li>HTTP 204 / <code>no_update</code> means up to date, not an error; 304 is an ETag hit.</li><li>Without a Replacer, do not describe one-click install.</li><li>Without a Patcher, do not advertise <code>binary_delta</code>.</li></ol>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};